import SwiftUI

/// Uses the exact contours generated by brand/build.py. This is an in-app reveal;
/// the OS launch screen stays static. No model, data loading or routing waits for it.
struct BrandReveal: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var drawn = false
    @State private var filled = false

    var body: some View {
        ZStack {
            BrandMarkShape()
                .trim(from: 0, to: drawn ? 1 : 0)
                .stroke(Theme.cobalt, style: StrokeStyle(lineWidth: 2, lineCap: .round, lineJoin: .round))
            BrandMarkShape().fill(Theme.cobalt).opacity(filled ? 1 : 0)
        }
        .aspectRatio(1, contentMode: .fit)
        .accessibilityLabel("Setecho")
        .task {
            if reduceMotion { drawn = true; filled = true; return }
            withAnimation(.easeOut(duration: 0.55)) { drawn = true }
            withAnimation(.easeOut(duration: 0.25).delay(0.4)) { filled = true }
        }
    }
}

/// A short, non-interactive first-window reveal. Never replayed on foregrounding.
struct BrandLaunchOverlay: ViewModifier {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var showing = true

    func body(content: Content) -> some View {
        content.overlay {
            if showing {
                VStack(spacing: Theme.Space.l) {
                    BrandReveal().frame(width: 96, height: 96)
                    Image("Wordmark").resizable().scaledToFit().frame(width: 180)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Theme.page.ignoresSafeArea())
                .allowsHitTesting(false)
                .accessibilityHidden(true)
                .transition(.opacity)
            }
        }
        .task {
            // A canceled task must never leave the overlay covering the app.
            try? await Task.sleep(for: .milliseconds(reduceMotion ? 150 : 800))
            withAnimation(.easeOut(duration: 0.18)) { showing = false }
        }
    }
}

